          "kind": "code",
          "language": "typescript",
          "code": "export const errorInterceptor: HttpInterceptorFn = (req, next) => {\n  const notify = inject(NotificationService);\n  const router = inject(Router);\n\n  return next(req).pipe(\n    catchError((err: HttpErrorResponse) => {\n      switch (err.status) {\n        case 401:\n          router.navigate(['/login']); // сесія стухла — це вже зробив authInterceptor,\n          break;                       // тут лише UX-реакція, не дублюємо redirect-логіку\n        case 403:\n          notify.error('Немає доступу до цієї дії');\n          break;\n        case 0:\n          notify.error('Немає з’єднання з сервером');\n          break;\n        default:\n          if (err.status >= 500) notify.error('Помилка сервера, спробуйте пізніше');\n      }\n      return throwError(() => err); // прокидаємо далі — виклику потрібно знати, що впало\n    })\n  );\n};\n\n// Порядок у withInterceptors важливий: виконуються по черзі, як middleware\nprovideHttpClient(\n  withInterceptors([authInterceptor, errorInterceptor])\n);"
