          "kind": "code",
          "language": "typescript",
          "code": "// SSE: HTTP-based, text/event-stream, автоматично reconnect\ngetNotifications(): Observable<Notification> {\n  return new Observable<Notification>(observer => {\n    const eventSource = new EventSource('/api/notifications');\n    eventSource.onmessage = (event) => {\n      observer.next(JSON.parse(event.data));\n    };\n    eventSource.onerror = () => observer.error(new Error('SSE error'));\n    return () => eventSource.close();\n  });\n}\n\n// SSE vs WebSocket: SSE проще (текст, автоматичний reconnect), WebSocket для bi-directional"
